function format(value: string): string;
function format(value: number): string;
function format(value: string | number): string {
  if (typeof value === 'number') {
    return value.toFixed(2);
  }
  return value.trim();
}

format(42);      // overload 2 — return string
format(' hi ');  // overload 1

function create(tag: string): HTMLElement;
function create(tag: string, children: string): HTMLElement;
function create(tag: string, children?: string): HTMLElement {
  const el = document.createElement(tag);
  if (children !== undefined) el.textContent = children;
  return el;
}

interface Converter {
  (input: string): number;
  (input: number): string;
}

const convert: Converter = (input: string | number) => {
  return typeof input === 'string' ? Number(input) : String(input);
} as Converter;

